```javascript
function egalProfond(a, b) {
  if (a === b) return true;
  // Cas NaN (NaN !== NaN mais structurellement identiques)
  if (typeof a === 'number' && typeof b === 'number' && Number.isNaN(a) && Number.isNaN(b)) {
    return true;
