function creerBST() {
  let root = null;

  function insert(val) {
    const newNode = { value: val, left: null, right: null };
    if (root === null) {
      root = newNode;
      return;
    }
    let current = root;
    while (true) {
      if (val < current.value) {
        if (current.left === null) { current.left = newNode; return; }
        current = current.left;
      } else {
        if (current.right === null) { current.right = newNode; return; }
        current = current.right;
      }
    }
  }

  function contains(val) {
    let current = root;
    while (current !== null) {
      if (val === current.value) return true;
      current = val < current.value ? current.left : current.right;
    }
    return false;
  }

  return { insert, contains };
}
// Test : insert(5), insert(3), insert(7) → contains(7) === true ✓ ; contains(4) === false ✓
```

