function memoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      return cache.get(key); // résultat servi depuis le cache
    }
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}
