# Post-Doctorat — Classe 1 (Tier 1) : Solutions

## tache_1a — File de priorité (min-heap)

Min-tas implémenté dans un tableau : insertion avec remontée (sift-up), extraction avec descente (sift-down). Complexité O(log n) par opération.

```javascript
function creerFilePriorite() {
  const heap = [];

  function enqueue(val, priorite) {
    heap.push({ val, priorite });
    let i = heap.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (heap[i].priorite < heap[parent].priorite) {
        [heap[i], heap[parent]] = [heap[parent], heap[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  function dequeue() {
    if (heap.length === 0) return undefined;
    if (heap.length === 1) return heap.pop().val;
    const racine = heap[0];
    heap[0] = heap.pop();
    let i = 0;
    const n = heap.length;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;
      if (gauche < n && heap[gauche].priorite < heap[plusPetit].priorite) plusPetit = gauche;
      if (droite < n && heap[droite].priorite < heap[plusPetit].priorite) plusPetit = droite;
      if (plusPetit === i) break;
      [heap[i], heap[plusPetit]] = [heap[plusPetit], heap[i]];
      i = plusPetit;
    }
    return racine.val;
  }

  function taille() {
    return heap.length;
  }

  return { enqueue, dequeue, taille };
}
```

## tache_1b — EventEmitter

Registre d'écouteurs par événement ; `emit` itère sur une copie pour tolérer les modifications pendant l'émission.

```javascript
function creerEventEmitter() {
  const evenements = {};

  return {
    on(event, fn) {
      if (!evenements[event]) evenements[event] = [];
      evenements[event].push(fn);
    },
    off(event, fn) {
      if (!evenements[event]) return;
      evenements[event] = evenements[event].filter((f) => f !== fn);
    },
    emit(event, ...args) {
      if (!evenements[event]) return;
      for (const fn of [...evenements[event]]) {
        fn(...args);
      }
    }
  };
}
```

## tache_1c — Zip de tableaux

Longueur commune = minimum des longueurs ; on construit les tuples position par position.

```javascript
function zip(...tableaux) {
  if (tableaux.length === 0) return [];
  const minLongueur = Math.min(...tableaux.map((t) => t.length));
  const resultat = [];
  for (let i = 0; i < minLongueur; i++) {
    resultat.push(tableaux.map((t) => t[i]));
  }
  return resultat;
}
```

## tache_1d — Débogage BFS

**Bug identifié** : `file.pop()` retire le dernier élément (LIFO → parcours en profondeur). Le BFS exige un **FIFO** : `file.shift()` retire le premier élément arrivé.

```javascript
function parcoursEnLargeur(graphe, depart) {
  const visites = [];
  const file = [depart];
  while (file.length > 0) {
    const noeud = file.shift(); // CORRECTION : shift() (FIFO) au lieu de pop() (LIFO)
    if (!visites.includes(noeud)) {
      visites.push(noeud);
      for (const voisin of (graphe[noeud] || [])) {
        file.push(voisin);
      }
    }
  }
  return visites;
}
```

## tache_1e — Proxy manuel

Sans le built-in `Proxy`, on intercepte `get`/`set` via des accesseurs (`Object.defineProperty` avec `get`/`set`) définis pour chaque propriété de la cible ; chaque accès délègue au gestionnaire.

```javascript
function creerProxy(cible, gestionnaire) {
  const proxy = {};

  function definirAccesseur(prop) {
    Object.defineProperty(proxy, prop, {
      get() {
        if (gestionnaire && typeof gestionnaire.get === 'function') {
          return gestionnaire.get(cible, prop);
        }
        return cible[prop];
      },
      set(valeur) {
        if (gestionnaire && typeof gestionnaire.set === 'function') {
          gestionnaire.set(cible, prop, valeur);
        } else {
          cible[prop] = valeur;
        }
        return true;
      },
      enumerable: true,
      configurable: true
    });
  }

  for (const prop of Object.keys(cible)) {
    definirAccesseur(prop);
  }

  return proxy;
}
```

