```javascript
function puissance(base, exp) {
  let resultat = 1;
  for (let i = 0; i < exp; i++) {
    resultat *= base;
  }
  return resultat;
}
```

## algo_moyen_1 — Comptage de pairs

```javascript
function compterPairs(tab) {
  let compteur = 0;
  for (const x of tab) {
    if (x % 2 === 0) compteur++;
  }
  return compteur;
}
```

## algo_difficile_1 — Suppression de doublons

`Set` pour O(1) en recherche, en préservant l'ordre de première occurrence.

```javascript
function supprimerDoublons(tab) {
  const vus = new Set();
  const resultat = [];
  for (const x of tab) {
    if (!vus.has(x)) {
      vus.add(x);
      resultat.push(x);
    }
  }
  return resultat;
}
```

## algo_defi — Somme des pairs

```javascript
function sommePaires(tab) {
  let somme = 0;
  for (const x of tab) {
    if (x % 2 === 0) somme += x;
  }
  return somme;
}
```

