### tache_1b — [1-B] EventEmitter

```javascript
function creerEventEmitter() {
  const ecouteurs = {}; // nom d'événement -> tableau de fonctions

  return {
    on: function (event, fn) {
      if (!ecouteurs[event]) ecouteurs[event] = [];
      ecouteurs[event].push(fn);
      return this;
    },
    off: function (event, fn) {
      const liste = ecouteurs[event];
      if (!liste) return this;
      ecouteurs[event] = liste.filter(function (f) { return f !== fn; });
      return this;
    },
    emit: function (event) {
      const args = Array.prototype.slice.call(arguments, 1);
      const liste = ecouteurs[event];
      if (!liste || liste.length === 0) return false;
      const copie = liste.slice(); // évite les mutations pendant l'émission
      for (let i = 0; i < copie.length; i++) {
        copie[i].apply(null, args);
      }
      return true;
    }
  };
}
```

