# Post-Doctorat — Classe 1 (Tier 1) : Solutions

## tache_1a — File de priorité (min-heap)

Min-tas implémenté dans un tableau : insertion avec remontée (sift-up), extraction avec descente (sift-down). Complexité O(log n) par opération.

```javascript
function creerFilePriorite() {
  const heap = [];

  function enqueue(val, priorite) {
    heap.push({ val, priorite });
    let i = heap.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (heap[i].priorite < heap[parent].priorite) {
        [heap[i], heap[parent]] = [heap[parent], heap[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  function dequeue() {
    if (heap.length === 0) return undefined;
    if (heap.length === 1) return heap.pop().val;
    const racine = heap[0];
    heap[0] = heap.pop();
    let i = 0;
    const n = heap.length;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;
      if (gauche < n && heap[gauche].priorite < heap[plusPetit].priorite) plusPetit = gauche;
      if (droite < n && heap[droite].priorite < heap[plusPetit].priorite) plusPetit = droite;
      if (plusPetit === i) break;
      [heap[i], heap[plusPetit]] = [heap[plusPetit], heap[i]];
      i = plusPetit;
    }
    return racine.val;
  }

  function taille() {
    return heap.length;
  }

  return { enqueue, dequeue, taille };
}
```

