Registre d'écouteurs par événement ; `emit` itère sur une copie pour tolérer les modifications pendant l'émission.

```javascript
function creerEventEmitter() {
  const evenements = {};

  return {
    on(event, fn) {
      if (!evenements[event]) evenements[event] = [];
      evenements[event].push(fn);
    },
    off(event, fn) {
      if (!evenements[event]) return;
      evenements[event] = evenements[event].filter((f) => f !== fn);
    },
    emit(event, ...args) {
