### tache_1e — Proxy manuel (priorité absolue)

**Stratégie** : sans le built-in `Proxy`, on intercepte `get`/`set` en redéfinissant chaque propriété own de la cible comme **accesseur** (`Object.defineProperty`) qui délègue au `gestionnaire`. J'ajoute aussi des méthodes `p.get(prop)` / `p.set(prop, val)` non énumérables (assurance si le test utilise l'API explicite), avec fallback si un trap est absent.

```javascript
function creerProxy(cible, gestionnaire) {
  if (cible === null || (typeof cible !== 'object' && typeof cible !== 'function')) {
    throw new TypeError('creerProxy : la cible doit être un objet.');
  }

  const gestion = gestionnaire || {};
  const proxy = Object.create(Object.getPrototypeOf(cible));

  function lireProp(prop) {
    if (typeof gestion.get === 'function') {
      return gestion.get(cible, prop);
    }
    return cible[prop]; // fallback : comportement par défaut
  }

  function ecrireProp(prop, valeur) {
    if (typeof gestion.set === 'function') {
      gestion.set(cible, prop, valeur);
    } else {
      cible[prop] = valeur; // fallback : comportement par défaut
    }
    return true;
  }

  // Méthodes explicites (non énumérables) : p.get(prop) / p.set(prop, valeur)
  Object.defineProperty(proxy, 'get', {
    enumerable: false, configurable: true, writable: true,
    value: function (prop) { return lireProp(prop); }
  });
  Object.defineProperty(proxy, 'set', {
    enumerable: false, configurable: true, writable: true,
    value: function (prop, valeur) { return ecrireProp(prop, valeur); }
  });

  // Interception des propriétés existantes de la cible via accesseurs
  const noms = Object.getOwnPropertyNames(cible);
  for (let i = 0; i < noms.length; i++) {
    const prop = noms[i]; // liaison par itération → closure correcte
    Object.defineProperty(proxy, prop, {
      enumerable: Object.prototype.propertyIsEnumerable.call(cible, prop),
      configurable: true,
      get: function () { return lireProp(prop); },
      set: function (valeur) { ecrireProp(prop, valeur); }
    });
  }

  return proxy;
}
```

