```javascript
function creerFilePriorite() {
  const tas = [];
  let compteur = 0; // garantit la stabilité (FIFO) à priorité égale

  function echanger(i, j) {
    const tmp = tas[i]; tas[i] = tas[j]; tas[j] = tmp;
  }
  function aPrioriteSur(i, j) {
    if (tas[i].priorite !== tas[j].priorite) return tas[i].priorite < tas[j].priorite;
    return tas[i].ordre < tas[j].ordre;
  }
  function remonter(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (aPrioriteSur(i, parent)) { echanger(i, parent); i = parent; }
      else break;
    }
  }
  function descendre(i) {
    while (true) {
      const g = 2 * i + 1, d = 2 * i + 2;
      let mini = i;
      if (g < tas.length && aPrioriteSur(g, mini)) mini = g;
      if (d < tas.length && aPrioriteSur(d, mini)) mini = d;
      if (mini === i) break;
      echanger(i, mini);
      i = mini;
    }
  }

  return {
    enqueue: function (val, priorite) {
      const p = (priorite === undefined) ? Infinity : priorite;
      tas.push({ valeur: val, priorite: p, ordre: compteur++ });
      remonter(tas.length - 1);
    },
    dequeue: function () {
      if (tas.length === 0) return undefined;
      const racine = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return racine.valeur;
    },
    taille: function () {
      return tas.length;
    }
  };
}
