function calculerSomme(a, b) {
  function toNum(v) {
    if (typeof v === 'number') return v;
    if (typeof v === 'string' && v.trim() !== '') return Number(v.trim());
    if (typeof v === 'boolean') return v ? 1 : 0;
    return NaN;
  }
  const na = toNum(a);
  const nb = toNum(b);
  if (Number.isNaN(na) || Number.isNaN(nb)) return NaN;
  return na + nb;
}

function optimisation_extreme(arr, target) {
  // Recherche en O(N) avec un Set : pour chaque x, on cherche (target - x) déjà vu.
  const seen = new Set();
  for (let i = 0; i < arr.length; i++) {
    const x = arr[i];
    if (seen.has(target - x)) return true;
    seen.add(x);
  }
  return false;
}

function fusionnerIntervalles(tab) {
  if (!Array.isArray(tab) || tab.length === 0) return [];
  const sorted = [...tab].sort((p, q) => p[0] - q[0]);
  const merged = [sorted[0].slice()];
  for (let i = 1; i < sorted.length; i++) {
    const last = merged[merged.length - 1];
    const cur = sorted[i];
    if (cur[0] <= last[1]) {
      last[1] = Math.max(last[1], cur[1]);
    } else {
      merged.push(cur.slice());
    }
  }
  return merged;
}

function prefixeCommun(tab) {
  if (!Array.isArray(tab) || tab.length === 0) return "";
  let prefix = tab[0];
  for (let i = 1; i < tab.length; i++) {
    let j = 0;
    while (j < prefix.length && j < tab[i].length && prefix[j] === tab[i][j]) {
      j++;
    }
    prefix = prefix.slice(0, j);
    if (prefix === "") return "";
  }
  return prefix;
}

function nombreDeBits1(n) {
  // Algorithme de Brian Kernighan : x & (x-1) efface le bit de poids faible à 1.
  let count = 0;
  let x = n >>> 0; // interprétation non-signée 32 bits
  while (x !== 0) {
    x &= x - 1;
    count++;
  }
  return count;
}

function medianeDeuxTries(a, b) {
  // Recherche binaire par partition — O(log(min(m, n)))
  if (a.length > b.length) {
    const tmp = a; a = b; b = tmp;
  }
  const m = a.length, n = b.length;
  const total = m + n;
  if (total === 0) return NaN;
  const half = Math.floor((total + 1) / 2);
  let lo = 0, hi = m;
  while (lo <= hi) {
    const i = Math.floor((lo + hi) / 2); // nb d'éléments de a dans la moitié gauche
    const j = half - i;                  // nb d'éléments de b dans la moitié gauche
    const aLeft  = i > 0 ? a[i - 1] : -Infinity;
    const aRight = i < m ? a[i]     :  Infinity;
    const bLeft  = j > 0 ? b[j - 1] : -Infinity;
    const bRight = j < n ? b[j]     :  Infinity;
    if (aLeft <= bRight && bLeft <= aRight) {
      if (total % 2 === 1) {
        return Math.max(aLeft, bLeft);
      }
      return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
    } else if (aLeft > bRight) {
      hi = i - 1;
    } else {
      lo = i + 1;
    }
  }
  return NaN; // entrées invalides (tableaux non triés)
}

function plusLongueSousSuiteCroissante(tab) {
  // Patience sorting + recherche dichotomique : O(N log N), sous-suite STRICTEMENT croissante.
  if (!Array.isArray(tab) || tab.length === 0) return 0;
  const tails = [];
  for (let k = 0; k < tab.length; k++) {
    const x = tab[k];
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1; // strict : remplace le premier élément >= x
      else hi = mid;
    }
    if (lo === tails.length) tails.push(x);
    else tails[lo] = x;
  }
  return tails.length;
}
